            include_str!("../../callisto-format/src/bump.rs"),
        ),
        (
            "callisto-format/src/changeset/mod.rs",
            include_str!("../../callisto-format/src/changeset/mod.rs"),
        ),
        ("callisto-vcs/src/lib.rs", include_str!("../../callisto-vcs/src/lib.rs")),
        (
            "callisto-changelog/src/error.rs",
            include_str!("../../callisto-changelog/src/error.rs"),
        ),
    ];

    /// Extracts every `code(E<digits>)` occurrence from `text`, in order of appearance. Deliberately
    /// a hand-rolled scan rather than a `regex` dependency — the pattern is fixed-shape and simple
    /// enough that adding a whole crate dependency for it isn't warranted.
    fn extract_diagnostic_codes(text: &str) -> Vec<String> {
        let mut codes = Vec::new();
        let mut rest = text;
        while let Some(start) = rest.find("code(E") {
            let after_marker = &rest[start + "code(".len()..];
            let digit_end = after_marker
                .find(|c: char| !c.is_ascii_digit() && c != 'E')
                .unwrap_or(after_marker.len());
            let candidate = &after_marker[..digit_end];
            // `code(` is also used for things like `code(callisto::foo)` in test-double
            // diagnostics elsewhere in the workspace (out of scope for this scan, since those
            // files aren't in `DIAGNOSTIC_CODE_SOURCE_FILES`) -- guard here anyway so a stray
            // non-numeric match can't silently produce a bogus "code".
            if candidate.len() > 1 && candidate[1..].chars().all(|c| c.is_ascii_digit()) {
                codes.push(candidate.to_string());
            }
            rest = &after_marker[digit_end..];
        }
        codes
    }

    /// Asserts that every `#[diagnostic(code(...))]` value across every file in
    /// [`DIAGNOSTIC_CODE_SOURCE_FILES`] is unique workspace-wide. Duplicate diagnostic codes are
    /// a real user-facing bug (E-codes are meant to be a stable, searchable identifier for one
    /// specific error condition) — see this test's doc comment on `DIAGNOSTIC_CODE_SOURCE_FILES`
    /// for the collision this replaced a broken, silently-incomplete version of the check.
    #[test]
    fn test_all_diagnostic_codes_are_unique() {
        let mut seen: std::collections::BTreeMap<String, &str> = std::collections::BTreeMap::new();
        for (file, text) in DIAGNOSTIC_CODE_SOURCE_FILES {
            for code in extract_diagnostic_codes(text) {
                if let Some(first_file) = seen.insert(code.clone(), file) {
                    panic!("Duplicate diagnostic code {code}: declared in both {first_file} and {file}");
                }
            }
        }
        assert!(
            seen.len() > 50,
            "expected at least 50 distinct diagnostic codes across the workspace (81 at the \
             time this test was written), got {} -- extract_diagnostic_codes likely stopped \
             matching real source (check DIAGNOSTIC_CODE_SOURCE_FILES's include_str! paths \
             still resolve)",
            seen.len()
        );
    }

    #[test]
    fn extract_diagnostic_codes_finds_every_code_in_a_small_fixture() {
        let text = r#"
            #[diagnostic(code(E001))]
            struct Foo;
            #[diagnostic(
                code(E042),
                help("do something")
            )]
            struct Bar;
        "#;
        assert_eq!(extract_diagnostic_codes(text), vec!["E001", "E042"]);
    }

    #[test]
    fn extract_diagnostic_codes_detects_a_duplicate_within_one_string() {
        let text = "code(E001) ... code(E001)";
        let codes = extract_diagnostic_codes(text);
        let mut seen = std::collections::BTreeSet::new();
        assert!(!codes.iter().all(|c| seen.insert(c.clone())));
    }
}
use std::cmp::Ordering;
use std::fmt;
use std::str::FromStr;

use schemars::JsonSchema;
use serde::{Deserialize, Deserializer, Serialize, Serializer};

use crate::{Ecosystem, ModelError};

/// Package identity across ecosystems.
#[derive(Clone, Debug, PartialEq, Eq, Hash, JsonSchema)]
#[schemars(with = "String")]
pub enum PackageId {
    Bare(String),
    Prefixed { ecosystem: Ecosystem, name: String },
}

impl PackageId {
    /// Parses package identity string.
    ///
    /// # Errors
    ///
    /// Returns `Err` if `s` is empty, starts with `/`, contains `..`, or has a known ecosystem prefix followed by an empty name.
    pub fn parse(s: &str) -> Result<Self, PackageIdParseError> {
        if s.is_empty() {
            return Err(PackageIdParseError::Empty);
        }
        if s.starts_with('/') {
            return Err(PackageIdParseError::LeadingSlash { raw: s.to_string() });
        }
        if s.starts_with('-') {
            return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
        }
        if s.contains("..") {
            return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
        }

        if let Some((prefix, remainder)) = s.split_once(':') {
            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
                if remainder.is_empty() {
                    return Err(PackageIdParseError::EmptyNameAfterPrefix {
                        raw: s.to_string(),
                        prefix: prefix.to_string(),
                    });
                }
                if remainder.starts_with('-') {
                    return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
                }
                if remainder.contains("..") {
                    return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
                }
                return Ok(PackageId::Prefixed {
                    ecosystem,
                    name: remainder.to_string(),
                });
            }
        }

        if let Some((prefix, remainder)) = s.split_once('/') {
            if let Some(ecosystem) = Ecosystem::from_prefix(prefix) {
                if remainder.is_empty() {
                    return Err(PackageIdParseError::EmptyNameAfterPrefix {
                        raw: s.to_string(),
                        prefix: prefix.to_string(),
                    });
                }
                if remainder.starts_with('-') {
                    return Err(PackageIdParseError::LeadingHyphen { raw: s.to_string() });
                }
                if remainder.contains("..") {
                    return Err(PackageIdParseError::PathTraversal { raw: s.to_string() });
                }
                return Ok(PackageId::Prefixed {
                    ecosystem,
                    name: remainder.to_string(),
                });
            }
        }

        Ok(PackageId::Bare(s.to_string()))
    }

    /// Returns the canonical display form: bare names as-is, prefixed ids as `ecosystem/name`.
    pub fn display_name(&self) -> String {
        match self {
            PackageId::Bare(name) => name.clone(),
            PackageId::Prefixed { ecosystem, name } => {
                format!("{}/{}", ecosystem.prefix(), name)
            }
        }
    }

    /// Returns the ecosystem this id is scoped to, or `None` for a [`PackageId::Bare`] id.
    pub fn ecosystem(&self) -> Option<Ecosystem> {
        match self {
            PackageId::Bare(_) => None,
            PackageId::Prefixed { ecosystem, .. } => Some(*ecosystem),
        }
    }

    /// Returns the package name without any ecosystem prefix.
    pub fn name(&self) -> &str {
        match self {
            PackageId::Bare(name) => name,
            PackageId::Prefixed { name, .. } => name,
        }
    }

    /// Weak "could be the same package" check, not strict equality.
    ///
    /// `Bare(x)` matches any `Prefixed(_, x)` (bare is an ecosystem wildcard);
    /// `Prefixed(e1, x)` matches `Prefixed(e2, x)` only if `e1 == e2`; exact
    /// equality always matches.
    ///
    /// **Caller contract**: in a polyglot workspace, a bare lookup can match
    /// packages in two or more ecosystems (e.g. `foo` in both Cargo and npm).
    /// Callers must collect *all* matches and error on 2+ — see
    /// `aggregate::resolve_target_package`'s `AmbiguousName` pattern — never
    /// take the first match silently. A plain existence check (`.any()`) is
    /// safe only because the aggregation layer already rejects ambiguous
    /// references upstream.
    pub fn matches(&self, other: &Self) -> bool {
        if self == other {
            return true;
        }
        if self.name() == other.name() {
            match (self.ecosystem(), other.ecosystem()) {
                (None, _) | (_, None) => true,
                (Some(e1), Some(e2)) => e1 == e2,
            }
        } else {
            false
        }
    }

    /// The single implementation of the collect-and-error pattern
    /// [`matches`](Self::matches)'s own doc comment requires every caller
    /// to hand-roll: filters `items` down to those whose id (via `id_of`)
    /// matches `self`, then resolves the result to exactly one, none, or
    /// reports the ambiguity.
    ///
    /// - `Ok(None)`: no item matches.
    /// - `Ok(Some(item))`: exactly one item matches -- the unambiguous case.
    /// - `Err(candidates)`: two or more items match. The caller decides how
    ///   to report this (e.g. as a domain-specific "ambiguous name" error
    ///   naming `self` and `candidates`) -- this method stays generic over
    ///   any `T` (a `Package`, a bare `PackageId`, ...) rather than forcing
    ///   a particular error type on every layer that needs this check.
    pub fn resolve_unique<'a, T>(
        &self,
        items: impl Iterator<Item = &'a T>,
        id_of: impl Fn(&'a T) -> &'a PackageId,
    ) -> Result<Option<&'a T>, Vec<&'a T>> {
        let matching: Vec<&'a T> = items.filter(|item| id_of(item).matches(self)).collect();
        match matching.len() {
            0 => Ok(None),
            1 => Ok(Some(matching[0])),
            _ => Err(matching),
        }
    }
}

/// Trait for package identity resolution across ecosystem boundaries.
pub trait PackageIdentityResolver {
    /// Returns true if two package IDs refer to the same logical package.
    fn matches_id(&self, other: &PackageId) -> bool;
}

impl PackageIdentityResolver for PackageId {
    fn matches_id(&self, other: &PackageId) -> bool {
        self.matches(other)
    }
}

impl fmt::Display for PackageId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.display_name())
    }
}

impl FromStr for PackageId {
    type Err = PackageIdParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        PackageId::parse(s)
    }
}

impl PartialOrd for PackageId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for PackageId {
    fn cmp(&self, other: &Self) -> Ordering {
        let key_self = (self.ecosystem(), self.name());
        let key_other = (other.ecosystem(), other.name());
        key_self.cmp(&key_other)
    }
}

impl Serialize for PackageId {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        serializer.serialize_str(&self.display_name())
    }
}

impl<'de> Deserialize<'de> for PackageId {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>,
    {
        let s = String::deserialize(deserializer)?;
        PackageId::parse(&s).map_err(serde::de::Error::custom)
    }
}

/// Errors produced by [`PackageId::parse`].
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[non_exhaustive]
pub enum PackageIdParseError {
    #[error("package identity is empty")]
    Empty,
    #[error("package identity `{raw}` has ecosystem prefix `{prefix}` but no name after it")]
    EmptyNameAfterPrefix { raw: String, prefix: String },
    #[error("`{raw}` starts with `/`")]
    LeadingSlash { raw: String },
    #[error("package identity `{raw}` contains path traversal `..`")]
    PathTraversal { raw: String },
    #[error("package identity `{raw}` starts with `-`, which could be misread as a command-line flag")]
    LeadingHyphen { raw: String },
}

/// A group name for fixed or linked package groups.
#[derive(Clone, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[schemars(with = "String")]
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};

use crate::{NpmAccess, RegistryKey, VersionGrammar};

/// Ecosystem supported by callisto.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
#[non_exhaustive]
pub enum Ecosystem {
    Cargo,
    Npm,
    // Demand-gated ecosystems:
    Pypi,
    Go,
    Maven,
    NuGet,
    Deno,
    Jsr,
}

impl Ecosystem {
    pub fn prefix(&self) -> &'static str {
        match self {
            Ecosystem::Cargo => "cargo",
            Ecosystem::Npm => "npm",
            Ecosystem::Pypi => "pypi",
            Ecosystem::Go => "go",
            Ecosystem::Maven => "maven",
            Ecosystem::NuGet => "nuget",
            Ecosystem::Deno => "deno",
            Ecosystem::Jsr => "jsr",
        }
    }

    pub fn from_prefix(s: &str) -> Option<Self> {
        match s.to_ascii_lowercase().as_str() {
            "cargo" => Some(Ecosystem::Cargo),
            "npm" => Some(Ecosystem::Npm),
            "pypi" => Some(Ecosystem::Pypi),
            "go" => Some(Ecosystem::Go),
            "maven" => Some(Ecosystem::Maven),
            "nuget" => Some(Ecosystem::NuGet),
            "deno" => Some(Ecosystem::Deno),
            "jsr" => Some(Ecosystem::Jsr),
            _ => None,
        }
    }

    pub fn version_grammar(&self) -> VersionGrammar {
        match self {
            Ecosystem::Cargo | Ecosystem::Npm | Ecosystem::Deno | Ecosystem::Jsr | Ecosystem::NuGet | Ecosystem::Go => {
                VersionGrammar::SemVer
            }
            Ecosystem::Pypi => VersionGrammar::Pep440,
            Ecosystem::Maven => VersionGrammar::Maven,
        }
    }

    pub fn is_implemented(&self) -> bool {
        matches!(self, Ecosystem::Cargo | Ecosystem::Npm | Ecosystem::Pypi)
    }
}

/// Target registry or release location.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
#[non_exhaustive]
pub enum PublishTarget {
    CratesIo,
    Npm {
        registry: Option<String>,
        /// The operator's explicit `publishConfig.access` from `package.json`,
        /// if set. `None` means npm's `publishConfig.access` was absent --
        /// distinct from an explicit `"public"`, which a bare bool couldn't
        /// represent (both collapsed to `false`, silently dropping an
        /// unscoped package's explicit `"public"` setting). When `Some`,
        /// `plan_publish` passes the corresponding `--access` flag rather
        /// than falling back to the `@scope/name`-implies-public heuristic.
        access: Option<NpmAccess>,
    },
    Pypi {
        index: Option<String>,
    },
    NuGet {
        source: Option<String>,
    },
    GitHubRelease,
    None,
}

impl PublishTarget {
    pub fn registry_key(&self) -> Option<RegistryKey> {
        match self {
            PublishTarget::CratesIo => Some(RegistryKey(RegistryKey::CRATES_IO.to_string())),
            PublishTarget::Npm { .. } => Some(RegistryKey(RegistryKey::NPM.to_string())),
            PublishTarget::Pypi { .. } => Some(RegistryKey(RegistryKey::PYPI.to_string())),
            PublishTarget::NuGet { .. } => Some(RegistryKey(RegistryKey::NUGET.to_string())),
            PublishTarget::GitHubRelease | PublishTarget::None => None,
        }
    }

    pub fn ecosystem(&self) -> Option<Ecosystem> {
        match self {
            PublishTarget::CratesIo => Some(Ecosystem::Cargo),
            PublishTarget::Npm { .. } => Some(Ecosystem::Npm),
            PublishTarget::Pypi { .. } => Some(Ecosystem::Pypi),
            PublishTarget::NuGet { .. } => Some(Ecosystem::NuGet),
            PublishTarget::GitHubRelease | PublishTarget::None => None,
        }
    }

    /// The `publish-to` config string this variant parses from, mirroring
    /// `parse_publish_target` in `callisto_graph::config::resolve`. Used to
    /// name the mismatched target in diagnostics/errors without leaking the
    /// `Debug` representation of the variant's payload.
    pub fn config_str(&self) -> &'static str {
        match self {
            PublishTarget::CratesIo => "crates-io",
            PublishTarget::Npm { .. } => "npm",
            PublishTarget::Pypi { .. } => "pypi",
            PublishTarget::NuGet { .. } => "nuget",
            PublishTarget::GitHubRelease => "github-release",
            PublishTarget::None => "none",
        }
    }
}

/// PEP 503 / PEP 427 style Python package-name normalization: lowercase,
/// then collapse any run of hyphens, dots, or underscores into a single
/// underscore. This makes name-equality comparisons and wheel-filename
/// construction agree that "my-package", "my_package", "my.package", and
/// "My--Package" all refer to the same PyPI distribution -- PEP 503's own
/// canonicalization rule (`re.sub(r"[-_.]+", "-", name).lower()`), joined
/// with `_` to match PEP 427's wheel-filename escaping instead of PEP
/// 503's own `-` (the join character doesn't affect equality comparisons,
/// only which convention a caller building a filename needs).
pub fn normalize_pypi_package_name(name: &str) -> String {
    name.to_lowercase()
        .split(['-', '.', '_'])
        .filter(|s| !s.is_empty())
        .collect::<Vec<_>>()
        .join("_")
}

/// Trigger mechanism for generating releases.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "lowercase")]
pub enum ReleaseTrigger {
    #[default]
    Changeset,
    Auto,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_ecosystem_prefixes() {
        assert_eq!(Ecosystem::from_prefix("cargo"), Some(Ecosystem::Cargo));
        assert_eq!(Ecosystem::from_prefix("npm"), Some(Ecosystem::Npm));
        assert_eq!(Ecosystem::Cargo.prefix(), "cargo");
    }

    #[test]
    fn identifies_implemented_ecosystems() {
        assert!(Ecosystem::Cargo.is_implemented());
        assert!(Ecosystem::Npm.is_implemented());
        assert!(Ecosystem::Pypi.is_implemented());
    }

    #[test]
    fn normalize_pypi_package_name_treats_hyphen_underscore_dot_as_equivalent() {
        assert_eq!(normalize_pypi_package_name("my-package"), "my_package");
        assert_eq!(normalize_pypi_package_name("my_package"), "my_package");
        assert_eq!(normalize_pypi_package_name("my.package"), "my_package");
        assert_eq!(normalize_pypi_package_name("My--Package"), "my_package");
        assert_eq!(normalize_pypi_package_name("MY.PACKAGE"), "my_package");
    }

    #[test]
    fn normalize_pypi_package_name_collapses_mixed_runs() {
        assert_eq!(normalize_pypi_package_name("foo-.-bar"), "foo_bar");
        assert_eq!(normalize_pypi_package_name("foo___bar"), "foo_bar");
    }
}
